281	            return this.getLastName();
282	        }
283	        return this.title + " " + this.getLastName();
284	    }
285	
286	    /**
287	     * The owner's {@link #getTelephone() telephone} formatted for humans: the stored E.164
288	     * value rewritten as the country code, a space, then the national digits grouped in threes
289	     * separated by spaces (e.g. {@code '+61 412 345 678'}). The known country codes are
290	     * {@code '+61'} (Australia) and {@code '+1'} (NANP); any other E.164 value is split with a
291	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
292	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
293	     * derived from {@link #getTelephone()}.
294	     */
295	    @Transient
296	    public String getTelephoneDisplay() {
297	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
298	            return null;
299	        }
300	        String digits = this.telephone.substring(1);
301	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
302	        if (digits.length() <= countryCodeLength) {
303	            return this.telephone;
304	        }
305	        String countryCode = digits.substring(0, countryCodeLength);
306	        String national = digits.substring(countryCodeLength);
307	        StringBuilder grouped = new StringBuilder();
308	        for (int i = 0; i < national.length(); i++) {
309	            if (i > 0 && i % 3 == 0) {
310	                grouped.append(' ');
311	            }
312	            grouped.append(national.charAt(i));
313	        }
314	        return "+" + countryCode + " " + grouped;
315	    }
316	
317	    /**
318	     * The calendar year in which {@code date}'s fiscal year starts. The fiscal year starts on
319	     * 1 July, so a date in July–December belongs to the fiscal year starting that calendar year,
320	     * while a date in January–June belongs to the fiscal year that started the previous calendar
321	     * year.
322	     */
323	    private static int fiscalYearStart(LocalDate date) {
324	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
325	    }
326	
327	    /**
328	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the
329	     * calendar year in which the fiscal year starts (the fiscal year starts on 1 July), derived
330	     * from the business-day-adjusted {@link #getRegistrationDate() registrationDate}
331	     * (e.g. a registration date in October 2026 yields {@code 'FY26'}). Not persisted — derived
332	     * from {@link #getRegistrationDate()}.
333	     */
334	    @Transient
335	    public String getFiscalYear() {
336	        return "FY" + String.format("%02d", fiscalYearStart(this.registrationDate) % 100);
337	    }
338	
339	    /**
340	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
341	     * the last two digits of the {@link #getFiscalYear() fiscal year} derived from the
342	     * business-day-adjusted {@link #getRegistrationDate() registrationDate}
343	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
344	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
345	     */
346	    @Transient
347	    public String getMembershipNumber() {
348	        return this.customerCode + "-M" + String.format("%02d", fiscalYearStart(this.registrationDate) % 100);
349	    }
350	
351	    /**
352	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
353	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
354	     * Not persisted — derived from {@link #getCustomerCode()}.
355	     */
356	    @Transient
357	    public int getCheckDigit() {
358	        int sum = 0;
359	        boolean dbl = true;
360	        String code = this.customerCode == null ? "" : this.customerCode;
361	        for (int i = code.length() - 1; i >= 0; i--) {
362	            char c = code.charAt(i);
363	            if (c < '0' || c > '9') {
364	                continue;
365	            }
366	            int d = c - '0';
367	            if (dbl) {
368	                d *= 2;
369	                if (d > 9) {
370	                    d -= 9;
371	                }
372	            }
373	            sum += d;
374	            dbl = !dbl;
375	        }
376	        return (10 - (sum % 10)) % 10;
377	    }
378	
379	    /**
380	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an
381	     * {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
382	     * namesakeCount} is {@code 0}; adds {@code 2} for a household of {@code 3} or more members
383	     * ({@link #getHouseholdSize() householdSize}); adds {@code 3} for a tenure of one or more
384	     * elapsed fiscal years since the {@link #getRegistrationDate() registration date}'s fiscal
385	     * year (the fiscal year starts on 1 July). Not persisted — derived from {@link #getEmail()},
386	     * {@link #getNamesakeCount()}, {@link #getHouseholdSize()} and {@link #getRegistrationDate()}.
387	     */
388	    @Transient
389	    public int getMembershipPoints() {
390	        int points = 0;
391	        boolean hasEmail = this.email != null && !this.email.isBlank();
392	        if (hasEmail) {
393	            points += 2;
394	        }
395	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
396	        if (uniqueName) {
397	            points += 1;
398	        }
399	        if (this.householdSize != null && this.householdSize >= 3) {
400	            points += 2;
401	        }
402	        if (this.registrationDate != null
403	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate) >= 1) {
404	            points += 3;
405	        }
406	        return points;
407	    }
408	
409	    /**
410	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()
411	     * membershipPoints}: {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
412	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more, then capped at
413	     * {@link #getMembershipLevelCap() membershipLevelCap} when one applies (a new owner's level
414	     * cannot exceed one above the maximum level among its existing household members). Not
415	     * persisted — derived from {@link #getMembershipPoints()} and {@link #getMembershipLevelCap()}.
416	     */
417	    @Transient
418	    public int getMembershipLevel() {
419	        int points = getMembershipPoints();
420	        int level;
421	        if (points >= 6) {
422	            level = 4;
423	        }
424	        else if (points >= 4) {
425	            level = 3;
426	        }
427	        else if (points >= 2) {
428	            level = 2;
429	        }
430	        else {
431	            level = 1;
432	        }
433	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
434	            return this.membershipLevelCap;
435	        }
436	        return level;
437	    }
438	
439	    /**
440	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
441	     */
442	    private static final Map<String, String> CITY_REGION = Map.of(
443	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
444	
445	    /**
446	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
447	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
448	     */
449	    private static final Map<String, int[]> REGION_RANGE = Map.of(
450	        "NSW", new int[] {2000, 2099},
451	        "VIC", new int[] {3000, 3099},
452	        "QLD", new int[] {4000, 4099});
453	
454	    /**
455	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
456	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
457	     */
458	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
459	        "NSW", "Australia/Sydney",
460	        "VIC", "Australia/Melbourne",
461	        "QLD", "Australia/Brisbane");
462	
463	    /**
464	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
465	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
466	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
467	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
468	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
469	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
470	     * by the owner pipelines (e.g. postcode validation) rather than copied.
471	     */
472	    public static String regionFor(String postcode, String city) {
473	        String region = regionForPostcode(postcode);
474	        if (region != null) {
475	            return region;
476	        }
477	        String cityRegion = regionForCity(city);
478	        return cityRegion != null ? cityRegion : "UNKNOWN";
479	    }
480	
481	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
482	     * Brisbane->QLD), or {@code null} when the city has no known region. */
483	    public static String regionForCity(String city) {
484	        return city == null ? null : CITY_REGION.get(city);
485	    }
486	
487	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
488	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
489	     * range. */
490	    public static String regionForPostcode(String postcode) {
491	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
492	            return null;
493	        }
494	        int value = Integer.parseInt(postcode);
495	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
496	            int[] range = entry.getValue();
497	            if (value >= range[0] && value <= range[1]) {
498	                return entry.getKey();
499	            }
500	        }
501	        return null;
502	    }
503	
504	    /**
505	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
506	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
507	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
508	     * derived from {@link #getCustomerCode()}.
509	     */
510	    @Transient
511	    public String getLocality() {
512	        if (this.customerCode == null) {
513	            return "UNKNOWN";
514	        }
515	        int dash = this.customerCode.indexOf('-');
516	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
517	    }
518	
519	    /**
520	     * The owner's timezone: the IANA name for the owner's {@link #getLocality() locality}/region
521	     * from the fixed region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
522	     * QLD->Australia/Brisbane), or {@code null} when the region has no mapped timezone. Not
523	     * persisted — derived from {@link #getLocality()}.
524	     */
525	    @Transient
526	    public String getTimezone() {
527	        return REGION_TIMEZONE.get(getLocality());
528	    }
529	
530	    /**
531	     * Whether more than 80 owners had already been created today when this response was
532	     * built. Not persisted — populated for the response by the create and fetch pipelines
533	     * and defaults to {@code false} so every owner serialization carries the flag.
534	     */
535	    @Transient
536	    public boolean isBulkSignupWarning() {
537	        return this.bulkSignupWarning;
538	    }
539	
540	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
541	        this.bulkSignupWarning = bulkSignupWarning;
542	    }
543	
544	    /**
545	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
546	     * existing owner's last name and postcode with a different telephone. Not persisted —
547	     * populated for the response by the create and fetch pipelines and defaults to
548	     * {@code false} so every owner serialization carries the flag.
549	     */
550	    @Transient
551	    public boolean isPossibleDuplicate() {
552	        return this.possibleDuplicate;
553	    }
554	
555	    public void setPossibleDuplicate(boolean possibleDuplicate) {
556	        this.possibleDuplicate = possibleDuplicate;
557	    }
558	
559	    /**
560	     * The id of the existing owner this owner possibly duplicates (shared last name and
561	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
562	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
563	     */
564	    @Transient
565	    public Integer getPossibleDuplicateOf() {
566	        return this.possibleDuplicateOf;
567	    }
568	
569	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
570	        this.possibleDuplicateOf = possibleDuplicateOf;
571	    }
572	
573	    /**
574	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
575	     * is present, otherwise {@code 'PHONE'}.
576	     * Not persisted — derived from {@link #getEmail()}.
577	     */
578	    @Transient
579	    public String getContactPreference() {
580	        boolean hasEmail = this.email != null && !this.email.isBlank();
581	        return hasEmail ? "EMAIL" : "PHONE";
582	    }
583	
584	    /**
585	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
586	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
587	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
588	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
589	     * {@link #getRegistrationDate()}.
590	     */
591	    @Transient
592	    public String getAgeBand() {
593	        if (this.birthDate == null || this.registrationDate == null) {
594	            return null;
595	        }
596	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
597	        if (age < 18) {
598	            return "MINOR";
599	        }
600	        return age < 65 ? "ADULT" : "SENIOR";
601	    }
602	
603	    protected Set<Pet> getPetsInternal() {
604	        if (this.pets == null) {
605	            this.pets = new HashSet<>();
606	        }
607	        return this.pets;
608	    }
609	
610	    protected void setPetsInternal(Set<Pet> pets) {
611	        this.pets = pets;
612	    }
613	
614	    public List<Pet> getPets() {
615	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
616	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
617	        return Collections.unmodifiableList(sortedPets);
618	    }
619	
620	    public void setPets(List<Pet> pets) {
621	        this.pets = new HashSet<>(pets);
622	    }
623	
624	    public void addPet(Pet pet) {
625	        getPetsInternal().add(pet);
626	        pet.setOwner(this);
627	    }
628	
629	    /**
630	     * Return the Pet with the given name, or null if none found for this Owner.
631	     *
632	     * @param name to test
633	     * @return true if pet name is already in use
634	     */
635	    public Pet getPet(String name) {
636	        return getPet(name, false);
637	    }
638	
639	    /**
640	     * Return the Pet with the given name, or null if none found for this Owner.
641	     *
642	     * @param name to test
643	     * @return true if pet name is already in use
644	     */
645	    public Pet getPet(String name, boolean ignoreNew) {
646	        name = name.toLowerCase();
647	        for (Pet pet : getPetsInternal()) {
648	            if (!ignoreNew || !pet.isNew()) {
649	                String compName = pet.getName();
650	                compName = compName.toLowerCase();
651	                if (compName.equals(name)) {
652	                    return pet;
653	                }
654	            }
655	        }
656	        return null;
657	    }
658	
659	    public Pet getPet(Integer petId) {
660	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
661	    }
662	
663	    @Override
664	    public String toString() {
665	        return new ToStringCreator(this)
666	
667	            .append("id", this.getId())
668	            .append("new", this.isNew())
669	            .append("lastName", this.getLastName())
670	            .append("firstName", this.getFirstName())
671	            .append("address", this.address)
672	            .append("city", this.city)
673	            .append("telephone", this.telephone)
674	            .toString();
675	    }
676	}
