663	    @Override
664	    public String toString() {
665	        return new ToStringCreator(this)
666	
667	            .append("id", this.getId())
668	            .append("new", this.isNew())
669	            .append("lastName", this.getLastName())
670	            .append("firstName", this.getFirstName())
671	            .append("address", this.address)
672	            .append("city", this.city)
673	            .append("telephone", this.telephone)
674	            .toString();
